/**
 * Something that happened in the receiver.
 *
 * WHY: The dashboard shows a live list of sessions; the native shells show
 * a notification when a sender appears. Both need the same information, so
 * the event carries the whole picture instead of a name and a payload that
 * every host would have to interpret on its own.
 */
sealed class FfiReceiverEvent {
    
    /**
     * A peer connected and a session began.
     */
    data class SessionStarted(
        /**
         * The new session.
         */
        val `session`: FfiSessionSnapshot) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The negotiated video format changed during the session.
     */
    data class VideoFormatChanged(
        /**
         * The session the format belongs to.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * The new format.
         */
        val `format`: FfiVideoFormat) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The negotiated audio format changed during the session.
     */
    data class AudioFormatChanged(
        /**
         * The session the format belongs to.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * The new format.
         */
        val `format`: FfiAudioFormat) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The playback state of the sender changed.
     */
    data class PlaybackStateChanged(
        /**
         * The session the change belongs to.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * The new state, as the sender described it.
         */
        val `state`: kotlin.String) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The now-playing metadata changed.
     */
    data class MetadataChanged(
        /**
         * The session the metadata belongs to.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * The title of the track.
         */
        val `title`: kotlin.String?, 
        /**
         * The artist of the track.
         */
        val `artist`: kotlin.String?, 
        /**
         * The album of the track.
         */
        val `album`: kotlin.String?) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The artwork changed. `None` means the artwork was cleared.
     */
    data class ArtworkChanged(
        /**
         * The session the artwork belongs to.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * The artwork bytes, if there are any.
         */
        val `artwork`: kotlin.ByteArray?) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The session ended.
     */
    data class SessionEnded(
        /**
         * The session that ended.
         */
        val `sessionId`: kotlin.ULong, 
        /**
         * Why it ended.
         */
        val `reason`: kotlin.String) : FfiReceiverEvent() {
        companion object
    }
    
    /**
     * The status of a protocol engine changed.
     */
    data class ProtocolStatusChanged(
        /**
         * The new status of the protocol.
         */
        val `status`: FfiProtocolStatus) : FfiReceiverEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiReceiverEvent : FfiConverterRustBuffer<FfiReceiverEvent>{
    override fun read(buf: ByteBuffer): FfiReceiverEvent {
        return when(buf.getInt()) {
            1 -> FfiReceiverEvent.SessionStarted(
                FfiConverterTypeFfiSessionSnapshot.read(buf),
                )
            2 -> FfiReceiverEvent.VideoFormatChanged(
                FfiConverterULong.read(buf),
                FfiConverterTypeFfiVideoFormat.read(buf),
                )
            3 -> FfiReceiverEvent.AudioFormatChanged(
                FfiConverterULong.read(buf),
                FfiConverterTypeFfiAudioFormat.read(buf),
                )
            4 -> FfiReceiverEvent.PlaybackStateChanged(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> FfiReceiverEvent.MetadataChanged(
                FfiConverterULong.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            6 -> FfiReceiverEvent.ArtworkChanged(
                FfiConverterULong.read(buf),
                FfiConverterOptionalByteArray.read(buf),
                )
            7 -> FfiReceiverEvent.SessionEnded(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> FfiReceiverEvent.ProtocolStatusChanged(
                FfiConverterTypeFfiProtocolStatus.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiReceiverEvent) = when(value) {
        is FfiReceiverEvent.SessionStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiSessionSnapshot.allocationSize(value.`session`)
            )
        }
        is FfiReceiverEvent.VideoFormatChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterTypeFfiVideoFormat.allocationSize(value.`format`)
            )
        }
        is FfiReceiverEvent.AudioFormatChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterTypeFfiAudioFormat.allocationSize(value.`format`)
            )
        }
        is FfiReceiverEvent.PlaybackStateChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterString.allocationSize(value.`state`)
            )
        }
        is FfiReceiverEvent.MetadataChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterOptionalString.allocationSize(value.`title`)
                + FfiConverterOptionalString.allocationSize(value.`artist`)
                + FfiConverterOptionalString.allocationSize(value.`album`)
            )
        }
        is FfiReceiverEvent.ArtworkChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterOptionalByteArray.allocationSize(value.`artwork`)
            )
        }
        is FfiReceiverEvent.SessionEnded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sessionId`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is FfiReceiverEvent.ProtocolStatusChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiProtocolStatus.allocationSize(value.`status`)
            )
        }
    }

    override fun write(value: FfiReceiverEvent, buf: ByteBuffer) {
        when(value) {
            is FfiReceiverEvent.SessionStarted -> {
                buf.putInt(1)
                FfiConverterTypeFfiSessionSnapshot.write(value.`session`, buf)
                Unit
            }
            is FfiReceiverEvent.VideoFormatChanged -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterTypeFfiVideoFormat.write(value.`format`, buf)
                Unit
            }
            is FfiReceiverEvent.AudioFormatChanged -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterTypeFfiAudioFormat.write(value.`format`, buf)
                Unit
            }
            is FfiReceiverEvent.PlaybackStateChanged -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterString.write(value.`state`, buf)
                Unit
            }
            is FfiReceiverEvent.MetadataChanged -> {
                buf.putInt(5)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterOptionalString.write(value.`title`, buf)
                FfiConverterOptionalString.write(value.`artist`, buf)
                FfiConverterOptionalString.write(value.`album`, buf)
                Unit
            }
            is FfiReceiverEvent.ArtworkChanged -> {
                buf.putInt(6)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterOptionalByteArray.write(value.`artwork`, buf)
                Unit
            }
            is FfiReceiverEvent.SessionEnded -> {
                buf.putInt(7)
                FfiConverterULong.write(value.`sessionId`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FfiReceiverEvent.ProtocolStatusChanged -> {
                buf.putInt(8)
                FfiConverterTypeFfiProtocolStatus.write(value.`status`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





